vec4 GetBlur2(vec2 uv) { return texture(sampler_blur2, uv); }
vec4 GetBlur3(vec2 uv) { return texture(sampler_blur3, uv); }


void main() {
  vec4 ret = vec4(0.0);
  vec2 uv = vUv;
  float rad = vRadius;

    ret = texture( sampler_main, vUv ).xyz;
    vec2 uv2 = vUv;
    uv2.x -= (((uv2.x-.5)*.013)*(1+(ret*15)+(audioLow*.75)));
    uv2.y -= (((uv2.y-.5)*.013)*(1+(ret*15)+(audioHigh*.75)));
    // sample previous uFrame
    ret = texture( sampler_main, uv2 ).xyz;

    // darken (decay) over uTime
    ret *= 0.985;
    if(ret.y >= .6 && ret.z >= .6 && ret.x >= .6){
       ret = 0;
    }
    ret.y -= 0.00385;
    ret.xz -= 0.00285;

  fragColor = ret;
}

_shaderData.comp:
#version 300 es
precision highp float;

// VisualSynth uniforms
uniform float uTime;
uniform float uFrame;
uniform float uFps;
uniform float uRms;

// Audio uniforms
uniform float audioLow;      // bass
uniform float audioLowSmooth; // bass_att
uniform float audioMid;      // mid
uniform float audioMidSmooth; // mid_att
uniform float audioHigh;     // treb
uniform float audioHighSmooth; // treb_att

// Screen uniforms
uniform float uAspectX;
uniform float uAspectY;
uniform vec2 uAspect;
uniform vec2 uTexSize;

// Random values
uniform vec2 uRandomPreset;
uniform vec2 uRandomFrame;

// Input from vertex shader
in vec2 vUv;
in float vRadius;
in float vAngle;

// Output
out vec4 fragColor;

// Textures
uniform sampler2D sampler_main;
uniform sampler2D sampler_noise_lq;
uniform sampler2D sampler_noise_mq;
uniform sampler2D sampler_noise_hq;
uniform sampler2D sampler_blur1;
uniform sampler2D sampler_blur2;
uniform sampler2D sampler_blur3;

// Helper functions
float clamp01(float x) { return clamp(x, 0.0, 1.0); }
vec2 clamp01(vec2 x) { return clamp(x, vec2(0.0), vec2(1.0)); }
vec3 clamp01(vec3 x) { return clamp(x, vec3(0.0), vec3(1.0)); }
vec4 clamp01(vec4 x) { return clamp(x, vec4(0.0), vec4(1.0)); }

// Texture helper functions
vec4 GetPixel(vec2 uv) { return texture(sampler_main, uv); }
vec4 GetBlur1(vec2 uv) { return texture(sampler_blur1, uv); }
vec4 GetBlur2(vec2 uv) { return texture(sampler_blur2, uv); }
vec4 GetBlur3(vec2 uv) { return texture(sampler_blur3, uv); }


void main() {
  vec4 ret = vec4(0.0);
  vec2 uv = vUv;
  float rad = vRadius;

    ret = texture(sampler_pw_main, vUv).xyz;
    ret *= 2.00; //gamma

    vec2 uv2 = vUv;
    uv2.y = uv2.y-(.5*((ret.x+ret.y+ret.z)*abs(vUv.y*-1)));
    vec3 ret2 = texture( sampler_pw_main, uv2 ).xyz;

    vec2 uv3 = vUv;
    uv3.y = uv3.y+(.5*((ret.x+ret.y+ret.z)*abs(vUv.y-1)));
    vec3 ret3 = texture( sampler_pw_main, uv3 ).xyz;

    vec2 uv4 = vUv;
    uv4.x = uv4.x-(.5*((ret.x+ret.y+ret.z)*abs(vUv.x-1)));
    vec3 ret4 = texture( sampler_pw_main, uv4 ).xyz;

    vec2 uv5 = vUv;
    uv5.x = uv5.x+(1*((ret.x+ret.y+ret.z)*vUv.x));
    vec3 ret5 = texture( sampler_pw_main, uv5 ).xyz;

    ret2+=GetBlur1(uv2);
    ret2+=GetBlur2(uv2)*(.5+audioLow*.5);

    ret3+=GetBlur1(uv3);
    ret3+=GetBlur2(uv3)*(.5+audioLow*.5);

    ret4+=GetBlur1(uv4);
    ret4+=GetBlur2(uv4)*(.5+audioLow*.5);

    ret5+=GetBlur1(uv5);
    ret5+=GetBlur2(uv5)*(.5+audioLow*.5);

    ret = mix(ret,ret2,.5*vol_att);
    ret = mix(ret,ret3,.8*audioLowSmooth);
    ret = mix(ret,ret4,.8*audioMidSmooth);
    ret = mix(ret,ret5,.2*audioHighSmooth);

    ret += ret*ret;


  fragColor = ret;
}
